cd /home/claude
b() { cat newmf/jeux_pre.js newmf/jeux$1_body.js > newmf/jeux$1.js && python3 newmf/build_mf.py jeux$1 newmf/jeux$1.js "$2" site/jeux$1.html; }
[ -f newmf/jeux1_body.js ] && b 1 '{"title":"Théorie des jeux 1 – Stratégies dominantes et dilemme du prisonnier","h1":"Stratégies dominantes et dilemme du prisonnier","course":"Représenter un jeu, repérer les meilleures réponses et les stratégies dominantes, comprendre pourquoi l&#39;équilibre peut être inefficace","ex":"Concurrence publicitaire et jeu à stratégie dominante","badge":"MICROÉCONOMIE"}'
[ -f newmf/jeux2_body.js ] && b 2 '{"title":"Théorie des jeux 2 – Élimination des stratégies dominées","h1":"Élimination répétée des stratégies strictement dominées","course":"Raisonner sur la rationalité de l&#39;autre : dominance stricte, élimination itérée et ses limites","ex":"Résoudre un jeu par élimination répétée","badge":"MICROÉCONOMIE"}'
[ -f newmf/jeux3_body.js ] && b 3 '{"title":"Théorie des jeux 3 – Équilibre de Nash en stratégies pures","h1":"Équilibre de Nash en stratégies pures","course":"Meilleures réponses mutuelles : coordination, bataille des sexes, poule mouillée et équilibres multiples","ex":"Trouver les équilibres de Nash d&#39;un jeu fini","badge":"MICROÉCONOMIE"}'
[ -f newmf/jeux4_body.js ] && b 4 '{"title":"Théorie des jeux 4 – Stratégies mixtes","h1":"Équilibre de Nash en stratégies mixtes","course":"Jouer au hasard à bon escient : principe d&#39;indifférence, correspondances de meilleure réponse et existence d&#39;un équilibre","ex":"Équilibres en stratégies mixtes d&#39;un jeu sans équilibre pur et de la poule mouillée","badge":"MICROÉCONOMIE"}'
[ -f newmf/jeux5_body.js ] && b 5 '{"title":"Théorie des jeux 5 – Jeux séquentiels","h1":"Jeux séquentiels et induction à rebours","course":"Forme extensive, stratégies conditionnelles, menaces non crédibles et équilibre parfait en sous-jeux","ex":"Forme extensive, forme normale et équilibre parfait","badge":"MICROÉCONOMIE"}'
[ -f newmf/jeux6_body.js ] && b 6 '{"title":"Théorie des jeux 6 – Jeu d&#39;entrée, engagement et mille-pattes","h1":"Jeu d&#39;entrée, engagement et mille-pattes","course":"Crédibilité des menaces, valeur de l&#39;engagement, induction à rebours à plusieurs joueurs et ses paradoxes","ex":"Dissuader un entrant, s&#39;engager et raisonner à rebours à trois joueurs","badge":"MICROÉCONOMIE"}'
[ -f newmf/jeux7_body.js ] && b 7 '{"title":"Théorie des jeux 7 – Le dilemme du volontaire","h1":"Le dilemme du volontaire","course":"Témoignage d&#39;une agression : équilibres asymétriques, équilibre symétrique mixte et effet du nombre de témoins","ex":"Combien de témoins pour qu&#39;un appel soit passé ?","badge":"MICROÉCONOMIE"}'
[ -f newmf/jeux8_body.js ] && b 8 '{"title":"Théorie des jeux 8 – Jeux répétés","h1":"Jeux répétés et coopération","course":"Répéter le dilemme du prisonnier : horizon fini, stratégies de déclenchement, punitions limitées et théorème folk","ex":"Soutenir la coopération dans un dilemme du prisonnier répété","badge":"MICROÉCONOMIE"}'
[ -f newmf/jeux9_body.js ] && b 9 '{"title":"Théorie des jeux 9 – Information incomplète","h1":"Jeux à information incomplète","course":"Types, croyances et équilibre bayésien : le duopole de Cournot avec un coût privé","ex":"Cournot avec coût privé : équilibre bayésien et valeur de l&#39;information","badge":"MICROÉCONOMIE"}'
